-- REVIEW ONLY: three owner policy expressions, no privileges or business data changed.
BEGIN;
SET LOCAL search_path=pg_catalog,public;
SET LOCAL lock_timeout='2s';
LOCK TABLE storage.objects IN ACCESS EXCLUSIVE MODE;
DO $guard$ DECLARE pol record; BEGIN
SELECT * INTO pol FROM pg_catalog.pg_policies WHERE schemaname='storage' AND tablename='objects' AND policyname='Owners can delete own pending partner media'; IF NOT FOUND OR pol.cmd<>'DELETE' OR pol.roles<>ARRAY['authenticated']::name[] OR pol.permissive<>'PERMISSIVE' OR (CASE WHEN pol.cmd='INSERT' THEN pol.qual IS NOT NULL ELSE pol.with_check IS NOT NULL END) OR COALESCE(regexp_replace(CASE WHEN pol.cmd='INSERT' THEN pol.with_check ELSE pol.qual END,'\s+',' ','g'),'') NOT IN ('((bucket_id = ''partner-media-pending''::text) AND ((storage.foldername(name))[1] = (auth.uid())::text) AND (EXISTS ( SELECT 1 FROM partners p WHERE ((p.owner_id = auth.uid()) AND ((p.id)::text = (storage.foldername(p.name))[2])))))','((bucket_id = ''partner-media-pending''::text) AND ((storage.foldername(name))[1] = (auth.uid())::text) AND (EXISTS ( SELECT 1 FROM partners p WHERE ((p.owner_id = auth.uid()) AND ((p.id)::text = (storage.foldername(objects.name))[2])))))') THEN RAISE EXCEPTION 'Unexpected media policy definition; review required'; END IF;
SELECT * INTO pol FROM pg_catalog.pg_policies WHERE schemaname='storage' AND tablename='objects' AND policyname='Owners can upload own pending partner media'; IF NOT FOUND OR pol.cmd<>'INSERT' OR pol.roles<>ARRAY['authenticated']::name[] OR pol.permissive<>'PERMISSIVE' OR (CASE WHEN pol.cmd='INSERT' THEN pol.qual IS NOT NULL ELSE pol.with_check IS NOT NULL END) OR COALESCE(regexp_replace(CASE WHEN pol.cmd='INSERT' THEN pol.with_check ELSE pol.qual END,'\s+',' ','g'),'') NOT IN ('((bucket_id = ''partner-media-pending''::text) AND ((storage.foldername(name))[1] = (auth.uid())::text) AND (EXISTS ( SELECT 1 FROM partners p WHERE ((p.owner_id = auth.uid()) AND ((p.id)::text = (storage.foldername(p.name))[2])))))','((bucket_id = ''partner-media-pending''::text) AND ((storage.foldername(name))[1] = (auth.uid())::text) AND (EXISTS ( SELECT 1 FROM partners p WHERE ((p.owner_id = auth.uid()) AND ((p.id)::text = (storage.foldername(objects.name))[2])))))') THEN RAISE EXCEPTION 'Unexpected media policy definition; review required'; END IF;
SELECT * INTO pol FROM pg_catalog.pg_policies WHERE schemaname='storage' AND tablename='objects' AND policyname='Owners can view own pending partner media'; IF NOT FOUND OR pol.cmd<>'SELECT' OR pol.roles<>ARRAY['authenticated']::name[] OR pol.permissive<>'PERMISSIVE' OR (CASE WHEN pol.cmd='INSERT' THEN pol.qual IS NOT NULL ELSE pol.with_check IS NOT NULL END) OR COALESCE(regexp_replace(CASE WHEN pol.cmd='INSERT' THEN pol.with_check ELSE pol.qual END,'\s+',' ','g'),'') NOT IN ('((bucket_id = ''partner-media-pending''::text) AND ((storage.foldername(name))[1] = (auth.uid())::text) AND (EXISTS ( SELECT 1 FROM partners p WHERE ((p.owner_id = auth.uid()) AND ((p.id)::text = (storage.foldername(p.name))[2])))))','((bucket_id = ''partner-media-pending''::text) AND ((storage.foldername(name))[1] = (auth.uid())::text) AND (EXISTS ( SELECT 1 FROM partners p WHERE ((p.owner_id = auth.uid()) AND ((p.id)::text = (storage.foldername(objects.name))[2])))))') THEN RAISE EXCEPTION 'Unexpected media policy definition; review required'; END IF;
END $guard$;
ALTER POLICY "Owners can delete own pending partner media" ON storage.objects USING (((bucket_id = 'partner-media-pending'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text) AND (EXISTS ( SELECT 1
   FROM public.partners p
  WHERE ((p.owner_id = auth.uid()) AND ((p.id)::text = (storage.foldername(objects.name))[2]))))));
ALTER POLICY "Owners can upload own pending partner media" ON storage.objects WITH CHECK (((bucket_id = 'partner-media-pending'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text) AND (EXISTS ( SELECT 1
   FROM public.partners p
  WHERE ((p.owner_id = auth.uid()) AND ((p.id)::text = (storage.foldername(objects.name))[2]))))));
ALTER POLICY "Owners can view own pending partner media" ON storage.objects USING (((bucket_id = 'partner-media-pending'::text) AND ((storage.foldername(name))[1] = (auth.uid())::text) AND (EXISTS ( SELECT 1
   FROM public.partners p
  WHERE ((p.owner_id = auth.uid()) AND ((p.id)::text = (storage.foldername(objects.name))[2]))))));
COMMIT;
